package com.skillswap.web;

import com.skillswap.model.*;
import com.skillswap.repo.*;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;

@RestController @RequestMapping("/api")
public class CatalogController {
    private final CourseRepository courses;private final AppUserRepository users;private final EnrollmentRepository enrollments;private final ReviewRepository reviews;private final ApiSupport helper;
    CatalogController(CourseRepository courses,AppUserRepository users,EnrollmentRepository enrollments,ReviewRepository reviews,ApiSupport helper){this.courses=courses;this.users=users;this.enrollments=enrollments;this.reviews=reviews;this.helper=helper;}
    @GetMapping("/catalog/courses") public List<Map<String,Object>> browse(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String category){
        return courses.findByPublishedTrueOrderByCreatedAtDesc().stream().filter(c->(q.isEmpty()||(c.title+" "+c.description+" "+c.tags+" "+c.mentor.name).toLowerCase().contains(q.toLowerCase()))&&(category.isEmpty()||category.equalsIgnoreCase(c.category))).map(ApiSupport::course).toList();
    }
    @GetMapping("/catalog/courses/{id}")public Map<String,Object> course(@PathVariable Long id){Course c=courses.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!c.published)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return ApiSupport.course(c);}
    @GetMapping("/catalog/profiles/{id}")public Map<String,Object> publicProfile(@PathVariable Long id){AppUser u=users.findById(id).filter(x->x.active).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile unavailable"));return ApiSupport.publicUser(u);}
    @GetMapping("/catalog/mentors")public List<Map<String,Object>> mentors(){return users.findAll().stream().filter(u->u.mentor&&u.active).map(ApiSupport::publicUser).toList();}
    @GetMapping("/catalog/mentors/{id}")public Map<String,Object> mentor(@PathVariable Long id){AppUser u=users.findById(id).filter(x->x.mentor&&x.active).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return Map.of("mentor",ApiSupport.publicUser(u),"courses",courses.findByMentorIdOrderByCreatedAtDesc(id).stream().filter(c->c.published).map(ApiSupport::course).toList());}
    @GetMapping("/catalog/courses/{id}/reviews")public List<Map<String,Object>> reviews(@PathVariable Long id){return reviews.findByCourseIdOrderByCreatedAtDesc(id).stream().map(r->Map.<String,Object>of("id",r.id,"author",ApiSupport.publicUser(r.author),"stars",r.stars,"comment",r.comment,"createdAt",r.createdAt)).toList();}
    @GetMapping("/enrollments")public List<Map<String,Object>> mine(Authentication a){AppUser u=helper.me(a);return enrollments.findByLearnerIdOrderByEnrolledAtDesc(u.id).stream().map(e->Map.<String,Object>of("id",e.id,"course",ApiSupport.course(e.course),"progress",e.progress,"enrolledAt",e.enrolledAt)).toList();}
    @PostMapping("/enrollments/{id}/progress")public Map<String,Object> progress(Authentication a,@PathVariable Long id,@RequestBody Map<String,Object> form){AppUser u=helper.me(a);Enrollment e=enrollments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!e.learner.id.equals(u.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN);e.progress=(int)Math.min(100,Math.max(0,ApiSupport.num(form,"progress",e.progress)));enrollments.save(e);return Map.of("progress",e.progress);}
    @PostMapping("/courses/{id}/reviews")public Map<String,Object> addReview(Authentication a,@PathVariable Long id,@RequestBody Map<String,Object> f){AppUser u=helper.me(a);Course c=courses.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));ApiSupport.require(enrollments.existsByLearnerIdAndCourseId(u.id,id),"Buy this course before reviewing");ApiSupport.require(!reviews.existsByAuthorIdAndCourseId(u.id,id),"You have already reviewed this course");int stars=(int)ApiSupport.num(f,"stars",5);ApiSupport.require(stars>=1&&stars<=5,"Rating must be 1–5");Review r=new Review();r.author=u;r.course=c;r.stars=stars;r.comment=ApiSupport.str(f,"comment");reviews.save(r);var all=reviews.findByCourseIdOrderByCreatedAtDesc(id);c.rating=all.stream().mapToInt(x->x.stars).average().orElse(0);courses.save(c);return Map.of("saved",true);}
    @PostMapping("/mentor/courses")public Map<String,Object> addCourse(Authentication a,@RequestBody Map<String,Object> f){AppUser u=helper.mentor(a);Course c=new Course();c.mentor=u;fill(c,f);courses.save(c);return ApiSupport.course(c);}
    @PatchMapping("/mentor/courses/{id}")public Map<String,Object> editCourse(Authentication a,@PathVariable Long id,@RequestBody Map<String,Object> f){AppUser u=helper.mentor(a);Course c=courses.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!c.mentor.id.equals(u.id)&&!u.admin)throw new ResponseStatusException(HttpStatus.FORBIDDEN);fill(c,f);c.published=false;courses.save(c);return ApiSupport.course(c);}
    @GetMapping("/mentor/courses")public List<Map<String,Object>> mentorCourses(Authentication a){AppUser u=helper.mentor(a);return courses.findByMentorIdOrderByCreatedAtDesc(u.id).stream().map(ApiSupport::course).toList();}
    private void fill(Course c,Map<String,Object> f){String title=ApiSupport.str(f,"title");ApiSupport.require(title.length()>=5&&title.length()<=160,"Course title must contain 5–160 characters");c.title=title;c.description=ApiSupport.str(f,"description");c.category=ApiSupport.str(f,"category");c.level=ApiSupport.str(f,"level");c.tags=ApiSupport.str(f,"tags");String cover=ApiSupport.str(f,"cover");if(cover.startsWith("https://"))c.cover=cover;c.pricePaise=ApiSupport.num(f,"pricePaise",49900);ApiSupport.require(c.pricePaise>=10000&&c.pricePaise<=10000000,"Course price out of range");c.lessons=(int)ApiSupport.num(f,"lessons",8);c.durationMinutes=(int)ApiSupport.num(f,"durationMinutes",60);ApiSupport.require(c.durationMinutes>=15&&c.durationMinutes<=240,"Duration must be 15–240 minutes");}
}
